def solve(grid, start, goal):
    if start == goal:
        return [start]
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = set()
    path = [start]

    def backtrack(current):
        if current == goal:
            return True
        visited.add(current)
        for dr, dc in directions:
            new_r, new_c = current[0] + dr, current[1] + dc
            neighbor = (new_r, new_c)
            if 0 <= new_r < rows and 0 <= new_c < cols and grid[new_r][new_c] == '.' and neighbor not in visited:
                path.append(neighbor)
                if backtrack(neighbor):
                    return True
                path.pop()
        visited.remove(current)
        return False

    if backtrack(start):
        return path
    else:
        return []
