def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    sr, sc = start
    gr, gc = goal

    if grid[sr][sc] == '#' or grid[gr][gc] == '#':
        return []

    if start == goal:
        return [start]

    INF = float('inf')
    distance = [[INF for _ in range(cols)] for _ in range(rows)]
    predecessor = [[None for _ in range(cols)] for _ in range(rows)]
    distance[sr][sc] = 0

    for _ in range(rows * cols - 1):
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == '#':
                    continue
                current_dist = distance[i][j]
                if current_dist == INF:
                    continue
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < rows and 0 <= nj < cols:
                        if grid[ni][nj] != '#':
                            if distance[ni][nj] > current_dist + 1:
                                distance[ni][nj] = current_dist + 1
                                predecessor[ni][nj] = (i, j)

    if distance[gr][gc] == INF:
        return []

    path = []
    current = (gr, gc)
    while current is not None:
        path.append(current)
        r, c = current
        current = predecessor[r][c]
    path.reverse()

    return path
