import heapq

def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    INF = float('inf')
    dist = [[INF] * cols for _ in range(rows)]
    heap = []
    heapq.heappush(heap, (0, start[0], start[1], [start]))
    dist[start[0]][start[1]] = 0

    while heap:
        current_dist, row, col, path = heapq.heappop(heap)
        if (row, col) == goal:
            return path
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < rows and 0 <= new_col < cols:
                if grid[new_row][new_col] == '.':
                    new_dist = current_dist + 1
                    if new_dist < dist[new_row][new_col]:
                        dist[new_row][new_col] = new_dist
                        new_path = path + [(new_row, new_col)]
                        heapq.heappush(heap, (new_dist, new_row, new_col, new_path))
    return []
